test_that("LandscapeFragmentation matches landscapemetrics", {
  T <- town()
  f <- LandscapeFragmentation(T$grid)
  expect_equal(c(f$mesh, f$splitting, f$division, f$n_patches), c(24.6, 4.878048780487805, 0.795, 2.0), tolerance = 1e-12)
})

test_that("food deserts, sprawl, impervious, heat island and density", {
  f <- FoodDesert(c(4000, 4000, 900, 3000), c(1500, 100, 400, 1200), c(0.25, 0.25, 0.10, 0.12), c(40000, 40000, 70000, 45000),
                  rep(60000, 4), c(TRUE, TRUE, FALSE, TRUE))
  expect_identical(f$lila, c(TRUE, FALSE, FALSE, TRUE))
  expect_identical(SprawlEntropy(c(5, 5, 5, 5))$relative, 1)
  expect_identical(ImperviousIndices(c(0.1, 0.05), c(0.2, 0.4), c(0.3, 0.1), tir = c(0.8, 0.02))$impervious, c(TRUE, FALSE))
  expect_identical(UhiIntensity(c(30, 32, 26, 24), c(TRUE, TRUE, FALSE, FALSE))$intensity, 6)
  g <- as.matrix(expand.grid(0:120 / 20 - 3, 0:120 / 20 - 3))
  expect_equal(sum(PopulationDensitySurface(rbind(c(0, 0), c(0.5, 0.2)), c(10, 5), g, 1.2)$density) / 400, 15, tolerance = 1e-4)
})
